import zipfile
import re
import sys

def clean_xml(xml_content):
    return re.sub('<[^>]+>', ' ', xml_content)

def read_docx(path):
    try:
        with zipfile.ZipFile(path) as z:
            if 'word/document.xml' in z.namelist():
                xml = z.read('word/document.xml').decode('utf-8')
                text = clean_xml(xml)
                print(f"--- CONTENT OF {path} ---")
                print(text[:1000])
                print("---------------------------")
            else:
                print(f"No document.xml in {path}")
    except Exception as e:
        print(f"Error reading {path}: {e}")

def read_pptx(path):
    try:
        with zipfile.ZipFile(path) as z:
            # Try finding slides
            slides = [n for n in z.namelist() if n.startswith('ppt/slides/slide')]
            if slides:
                # Read first slide
                first_slide = sorted(slides)[0]
                xml = z.read(first_slide).decode('utf-8')
                text = clean_xml(xml)
                print(f"--- CONTENT OF {path} ---")
                print(text[:1000])
                print("---------------------------")
            else:
                print(f"No slides found in {path}")
    except Exception as e:
         print(f"Error reading {path}: {e}")

read_docx('/root/papers/music_history/paper_file_1.docx')
read_docx('/root/papers/music_history/paper_file_2.docx')
read_pptx('/root/papers/music_history/DAMOP.pptx')

